import React from 'react';

const Importancia = () => {
    return (
        <section>
            <h2>¿Por qué importa hoy?</h2>
            <p>
                La dictadura de los hermanos Tinoco sigue siendo un tema relevante porque permite comprender que la democracia no es un proceso automático ni permanente, sino una construcción que requiere vigilancia, participación ciudadana y fortalecimiento institucional.
            </p>
            <p>
                El conocimiento de este episodio contribuye a la formación de una ciudadanía más crítica e informada, capaz de valorar la importancia de la separación de poderes, el respeto al orden constitucional y la defensa de los derechos fundamentales. Asimismo, fortalece la memoria histórica y permite identificar los riesgos que representan los modelos autoritarios para la convivencia democrática.
            </p>
        </section>
    );
};

export default Importancia;
